import hashlib
import hmac
import os
import time
import unicodedata
from typing import Dict, Optional, Tuple
from dataclasses import dataclass, field
from threading import Lock


@dataclass
class Session:
    user_id: str
    token_hash: str
    created_at: float
    expires_at: float
    ip_address: str
    is_admin: bool = False


class SecureTokenStore:
    """Thread-safe session token store with HMAC verification."""

    def __init__(self, secret_key: bytes = None):
        self.secret_key = secret_key or os.urandom(32)
        self._sessions: Dict[str, Session] = {}
        self._lock = Lock()
        self._max_sessions = 10000
        self._session_ttl = 3600  # 1 hour

    def _compute_hmac(self, data: str) -> str:
        """Compute HMAC-SHA256 for token integrity."""
        return hmac.new(
            self.secret_key,
            data.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()

    def _normalize_username(self, username: str) -> str:
        """Normalize username to prevent homoglyph attacks.
        Uses NFKC normalization then casefolding."""
        normalized = unicodedata.normalize('NFKC', username)
        return normalized.casefold()

    def _generate_token(self, username: str, normalized: str) -> str:
        """Generate a secure random token bound to normalized username."""
        random_part = os.urandom(24).hex()
        timestamp = str(int(time.time()))
        token_data = f"{normalized}:{random_part}:{timestamp}"
        mac = self._compute_hmac(token_data)
        return f"{normalized}:{random_part}:{timestamp}:{mac}"

    def _validate_token_format(self, token: str) -> Optional[Tuple[str, str, str, str]]:
        """Validate token structure and HMAC integrity."""
        parts = token.split(':')
        if len(parts) != 4:
            return None
        username, random_part, timestamp, provided_mac = parts
        token_data = f"{username}:{random_part}:{timestamp}"
        expected_mac = self._compute_hmac(token_data)
        if not hmac.compare_digest(provided_mac, expected_mac):
            return None
        return (username, random_part, timestamp, provided_mac)

    def create_session(self, username: str, ip_address: str, is_admin: bool = False) -> Optional[str]:
        """Create a new session for the authenticated user."""
        if not username or len(username) > 128:
            return None

        # Normalize for storage key
        normalized = self._normalize_username(username)
        token = self._generate_token(username, normalized)
        token_hash = hashlib.sha256(token.encode('utf-8')).hexdigest()

        now = time.time()
        session = Session(
            user_id=normalized,
            token_hash=token_hash,
            created_at=now,
            expires_at=now + self._session_ttl,
            ip_address=ip_address,
            is_admin=is_admin
        )

        with self._lock:
            if len(self._sessions) >= self._max_sessions:
                self._evict_expired()
            self._sessions[normalized] = session

        return token

    def validate_session(self, token: str, ip_address: str) -> Optional[Session]:
        """Validate a session token and return session if valid."""
        parsed = self._validate_token_format(token)
        if parsed is None:
            return None

        username, _, timestamp, _ = parsed

        # Check token age from timestamp
        try:
            token_time = int(timestamp)
        except ValueError:
            return None

        if time.time() - token_time > self._session_ttl:
            return None

        # The username in token is already normalized (embedded at creation)
        lookup_key = username

        with self._lock:
            session = self._sessions.get(lookup_key)

        if session is None:
            return None

        # Verify session hasn't expired
        if time.time() > session.expires_at:
            with self._lock:
                self._sessions.pop(lookup_key, None)
            return None

        # Verify token hash matches stored session
        token_hash = hashlib.sha256(token.encode('utf-8')).hexdigest()
        if not hmac.compare_digest(token_hash, session.token_hash):
            return None

        return session

    def get_admin_session(self, token: str, ip_address: str) -> Optional[Session]:
        """Retrieve session only if user has admin privileges.
        Performs additional validation for admin access."""
        parsed = self._validate_token_format(token)
        if parsed is None:
            return None

        username, _, _, _ = parsed
        # Username in token is already normalized
        lookup_key = username

        with self._lock:
            session = self._sessions.get(lookup_key)

        if session is None:
            return None

        if not session.is_admin:
            return None

        # For admin, also verify IP binding
        if session.ip_address != ip_address:
            return None

        if time.time() > session.expires_at:
            return None

        # Additional: verify token hash for admin
        token_hash = hashlib.sha256(token.encode('utf-8')).hexdigest()
        if not hmac.compare_digest(token_hash, session.token_hash):
            return None

        return session

    def elevate_privileges(self, token: str, ip_address: str, admin_token: str) -> bool:
        """Elevate a user session to admin using an admin authorization token.
        The admin must validate their own session first."""
        # Validate the requesting admin
        admin_session = self.get_admin_session(admin_token, ip_address)
        if admin_session is None:
            return False

        # Validate the target user token fully
        target_session = self.validate_session(token, ip_address)
        if target_session is None:
            return False

        username_parsed = self._validate_token_format(token)
        if username_parsed is None:
            return False

        target_key = username_parsed[0]  # Already normalized in token

        with self._lock:
            sess = self._sessions.get(target_key)
            if sess is None:
                return False
            sess.is_admin = True

        return True

    def revoke_session(self, username: str) -> bool:
        """Revoke a user's session by username."""
        normalized = self._normalize_username(username)
        with self._lock:
            return self._sessions.pop(normalized, None) is not None

    def _evict_expired(self):
        """Remove expired sessions. Must be called with lock held."""
        now = time.time()
        expired = [k for k, v in self._sessions.items() if now > v.expires_at]
        for k in expired:
            del self._sessions[k]


class AuthMiddleware:
    """HTTP authentication middleware using SecureTokenStore."""

    def __init__(self, store: SecureTokenStore):
        self.store = store
        self._rate_limits: Dict[str, list] = {}
        self._rate_lock = Lock()
        self._max_attempts = 10
        self._window = 60

    def _check_rate_limit(self, ip: str) -> bool:
        """Returns True if request is within rate limits."""
        now = time.time()
        with self._rate_lock:
            if ip not in self._rate_limits:
                self._rate_limits[ip] = []
            attempts = self._rate_limits[ip]
            # Remove old attempts
            self._rate_limits[ip] = [t for t in attempts if now - t < self._window]
            if len(self._rate_limits[ip]) >= self._max_attempts:
                return False
            self._rate_limits[ip].append(now)
        return True

    def authenticate_request(self, headers: Dict[str, str], ip_address: str) -> Tuple[bool, Optional[Session]]:
        """Authenticate an incoming request."""
        if not self._check_rate_limit(ip_address):
            return (False, None)

        auth_header = headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return (False, None)

        token = auth_header[7:]
        session = self.store.validate_session(token, ip_address)

        if session is None:
            return (False, None)

        return (True, session)

    def authenticate_admin(self, headers: Dict[str, str], ip_address: str) -> Tuple[bool, Optional[Session]]:
        """Authenticate an admin request with IP binding."""
        if not self._check_rate_limit(ip_address):
            return (False, None)

        auth_header = headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return (False, None)

        token = auth_header[7:]
        session = self.store.get_admin_session(token, ip_address)

        if session is None:
            return (False, None)

        return (True, session)
